WHILE @Month <= @EndMonth 
BEGIN 
    INSERT @Expected (DatasetCode, SourceKey, RowLimit) 
    SELECT DatasetCode, DatasetCode + '_tripdata_' + CONVERT(CHAR(7), @Month, 126) + '.csv', 
@RowLimit 
